import{_ as i,C as n,o as d,c as p,a3 as e,b as E,w as a,a as l,E as o,a2 as A}from"./chunks/framework.C51MRPOx.js";const c=JSON.parse('{"title":"LoRA 微调","description":"","frontmatter":{},"headers":[],"relativePath":"LLM训练/LoRA微调.md","filePath":"LLM训练/LoRA微调.md","lastUpdated":null}'),h={name:"LLM训练/LoRA微调.md"};function B(s,t,_,b,u,m){const r=n("Mermaid");return d(),p("div",null,[t[2]||(t[2]=e('<h1 id="lora-微调" tabindex="-1">LoRA 微调 <a class="header-anchor" href="#lora-微调" aria-label="Permalink to &quot;LoRA 微调&quot;">​</a></h1><p>小模型已经会对话，缺的是一批领域事实：某个接口怎么调用、参数有哪些、旁边的示例长什么样。LoRA 在指定线性层旁边加一块低秩增量，训练时只更新这块增量，基座冻住。领域事实因此写进适配器，基座的通用能力留在原处。</p><p>下面按「文档和代码 → 指令数据 → 训练 → 推理服务」说明。秩、学习率和基座规格随模型和数据量重选，这里不给一套通用数字。</p><h2 id="先抽出可引用的事实" tabindex="-1">先抽出可引用的事实 <a class="header-anchor" href="#先抽出可引用的事实" aria-label="Permalink to &quot;先抽出可引用的事实&quot;">​</a></h2><p>指令由问法和回答组成。回答要能对回一条已经抽出的事实。事实来自两类原料，抽完之后对齐到同一份字段：名称、签名或路径、参数、一段可引用的示例、来源位置。这一步还没有问答。</p><table tabindex="0"><thead><tr><th>原料</th><th>怎么抽</th><th>留下什么</th></tr></thead><tbody><tr><td>HTML 接口文档</td><td>用 BeautifulSoup 这类解析器按标签取标题、参数表和代码块</td><td>一个接口一条记录。导航、页脚、重复侧栏丢掉</td></tr><tr><td>代码库</td><td>用 tree-sitter 这类语法树按函数或方法节点切开</td><td>签名、紧挨着的说明、相邻的调用示例</td></tr></tbody></table><p>整页或整文件先不要塞进样本。抽出来的条目才是以后写答案时要对回去的依据。</p>',7)),(d(),E(A,null,{default:a(()=>[o(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Html%5B%22HTML%20%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3%22%5D%20--%3E%20Entry%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E6%9D%A1%E7%9B%AE%3Cbr%2F%3E%E5%90%8D%E7%A7%B0%20%C2%B7%20%E5%8F%82%E6%95%B0%20%C2%B7%20%E7%A4%BA%E4%BE%8B%20%C2%B7%20%E6%9D%A5%E6%BA%90%22%5D%0A%20%20%20%20Code%5B%22%E4%BB%A3%E7%A0%81%E5%BA%93%22%5D%20--%3E%20Entry%0A%20%20%20%20Entry%20--%3E%20Pair%5B%22%E9%97%AE%E6%B3%95%20%2B%20%E9%94%9A%E5%AE%9A%E5%9C%A8%E6%9D%A1%E7%9B%AE%E4%B8%8A%E7%9A%84%E5%9B%9E%E7%AD%94%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=e('<h2 id="把事实扩成指令" tabindex="-1">把事实扩成指令 <a class="header-anchor" href="#把事实扩成指令" aria-label="Permalink to &quot;把事实扩成指令&quot;">​</a></h2><p>文档里的参数说明和代码里的调用示例拼成一条回答。问法用两种办法变多：</p><ul><li>同义改写：同一个接口换几种问法，例如怎么调用、参数是什么、给一个例子。</li><li>模板填充：问法模板里换上真实的函数名、参数名和示例。模板只允许填已经抽出的条目。</li></ul><p>这样可以把规模扩到原来的大约三倍。变多的是问法，每条回答仍然对得回源条目。模板若允许自由填写文档里没有的接口名，模型会把编造的调用一起学进去。</p><p>评测问法从原文档和原代码里留出。这些问法不参与改写，也不进入训练集。</p><h2 id="质量闭环" tabindex="-1">质量闭环 <a class="header-anchor" href="#质量闭环" aria-label="Permalink to &quot;质量闭环&quot;">​</a></h2><p>进训练前先做清洗和格式校验。</p><table tabindex="0"><thead><tr><th>检查</th><th>处理</th></tr></thead><tbody><tr><td>空字段</td><td>没有签名、没有示例，或问法、回答为空，丢掉</td></tr><tr><td>残缺抽取</td><td>签名被截断、参数表只剩半行、代码块没闭合，退回重抽</td></tr><tr><td>标记残留</td><td>页面标签、导航文字混进正文，丢掉或清掉再入库</td></tr><tr><td>过长</td><td>整页或整文件塞进一条样本、超出这次训练的长度上限，拆回条目或丢掉</td></tr><tr><td>对不回来源</td><td>回答里的函数名、参数在源条目中找不到，丢掉</td></tr><tr><td>泄漏</td><td>评测问法，或和评测只差几个字的改写，出现在训练里，从训练中拿掉</td></tr></tbody></table><p>样本格式收成推理时会用的对话：系统说明、用户问法、助手回答字段齐全。缺一段时训练仍能跑，上线时模板会对不上。</p><p>微调之后用验证集看坏例。验证集用没有参与改写的原问法。改写句留在训练里，用来覆盖换一种问法仍然要答对的情况。</p><p>坏例分三类，回到抽取或模板：</p><table tabindex="0"><thead><tr><th>坏例</th><th>回到哪里</th></tr></thead><tbody><tr><td>幻觉接口、编造参数</td><td>回答没有锚在源条目上。收紧模板，或把该接口的抽取补全</td></tr><tr><td>漏了必填参数</td><td>抽取时参数表丢了，或回答模板没有要求写全</td></tr><tr><td>答非所问</td><td>问法和条目配错，或多源合并时接上了另一个函数的示例</td></tr></tbody></table><p>学习率留到事实和格式已经对得上之后再动。损失在降、坏例的种类不变，说明还在拟合问法，条目或模板还没补上。</p>',13)),(d(),E(A,null,{default:a(()=>[o(r,{id:"mermaid-200",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Extract%5B%22%E6%8A%BD%E5%8F%96%E4%BA%8B%E5%AE%9E%22%5D%20--%3E%20Expand%5B%22%E6%89%A9%E5%85%85%E5%B9%B6%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20%20%20Expand%20--%3E%20Train%5B%22%E5%BE%AE%E8%B0%83%22%5D%0A%20%20%20%20Train%20--%3E%20Bad%5B%22%E9%AA%8C%E8%AF%81%E9%9B%86%E5%9D%8F%E4%BE%8B%22%5D%0A%20%20%20%20Bad%20--%3E%7C%22%E8%A1%A5%E6%9D%A1%E7%9B%AE%E6%88%96%E6%94%B9%E6%A8%A1%E6%9D%BF%22%7C%20Expand%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[l(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=e('<h2 id="训练时对齐的几件事" tabindex="-1">训练时对齐的几件事 <a class="header-anchor" href="#训练时对齐的几件事" aria-label="Permalink to &quot;训练时对齐的几件事&quot;">​</a></h2><p>PEFT 把 LoRA 适配器挂到基座的注意力和前馈线性层上，优化器只看到这部分参数。秩决定增量的容量：秩小，可训练参数和显存更少，领域条目多时可能记不住；秩大，容量更接近全参更新，也更吃显存。目标模块要和基座的层名对上，挂错层等于几乎没有训到增量。</p><p>DeepSpeed 把优化器状态拆到多张卡或卸到内存，用来放下训练时的优化器开销。数据加载和它对齐三件事：</p><ul><li>微批次是每张卡每次前向的样本数。梯度累积把若干个微批次合成一次参数更新。全局批次等于卡数 × 微批次 × 累积步数。这三项对不齐时，学习率日程和实际看到的数据量会错开。</li><li>损失只打在回答段。问法部分掩掉，模型不必把用户的问题再复读一遍。</li><li>对话模板、特殊符号和最大长度，与最终推理服务使用同一套。训练时多一个角色标记、推理时少一个，损失可以下降，上线格式仍然是错的。</li></ul><p>学习率、秩、训练步数写进配置。换基座就重选，不沿用上一个模型的数字。</p><h2 id="交给推理服务" tabindex="-1">交给推理服务 <a class="header-anchor" href="#交给推理服务" aria-label="Permalink to &quot;交给推理服务&quot;">​</a></h2><p>训完保留适配器权重，以及它对应的基座版本。SGLang 一类服务按这个基座加载适配器。也可以把适配器合并进基座再导出。两种交付选一种：服务若同时看到未合并的基座和已经合并过的权重，等于加载了两套增量。</p><p>上线前用训练时留下的那套坏例再跑一遍，核对函数名、参数、示例是否还在，对话模板是否和训练一致。格式对齐之后，再看新的问法。</p>',8))])}const D=i(h,[["render",B]]);export{c as __pageData,D as default};
